from lib import *
S = SS('l45')
steps = [
    step("feature 上有 F1、F2、F3 三个提交(作者 Alice),main 在分叉之后又有了 M2、M3。Bob 执行 git rebase main:git log 里 F3、F2、F1 三个提交的作者仍是 Alice,提交者变成 Bob——和上一章 cherry-pick 一样,作者保留,提交者换成动手的人。它们的 hash 全部是新的:旧F1 → 新F1 的 parent 从 M1 变成 M3,旧F2 → 新F2 的 parent 是前一个新提交……三个新提交的 tree 都和旧的不同,因为它们都建立在 M3 之上:旧F1 的 tree 里只有 a、f1,新F1 的 tree 有 a、f1、m2、m3。", t=tl(S(1)), mark=lidx(S(1), 'committer=Bob', '旧F1 → 新F1', '新F1 的文件'), done=lidx(S(1), 'committer=Alice', 'main 的末端: M3'), kv=KV([['作者', '保留(Alice)'], ['提交者', '换成执行 rebase 的人(Bob)'], ['hash', '全是新的:parent 变了'], ['tree', '都带上了 main 新增的文件']], ['hash'])),
    step("旧提交没有消失:ORIG_HEAD 指向旧的末端 F3(True),没有任何分支包含旧F3(0 个),但 reflog 记着每一步:rebase (start): checkout main、三次 rebase (pick) F1/F2/F3、rebase (finish): returning to refs/heads/feature,再往前是 checkout 和 M3、M2 的提交。git range-diff main ORIG_HEAD feature 把新旧两组提交一一配对:1: c58861a = 1: 15e5082 F1,等号表示改动内容相同(只是换了基础)。", t=tl(S(2)), mark=lidx(S(2), 'rebase (finish)', 'rebase (pick): F1', 'rebase (start)', '1:  c58861a = 1:  15e5082 F1'), done=lidx(S(2), 'ORIG_HEAD 指向旧F3', 'git range-diff', '2:  e30e803', '3:  7f32687'), kv=KV([['ORIG_HEAD', '旧的末端'], ['reflog', 'start、每个 pick、finish'], ['range-diff', '把新旧提交一一配对,= 表示改动相同']], ['range-diff'])),
    step("rebase 中途停下来(这里 M4 也新增了 f2,和 F2 add/add 冲突)时,.git/rebase-merge/ 目录记录了全部状态:head-name 是 refs/heads/feature(正在改写的分支),onto 是新基础,orig-head 是旧的末端,msgnum 是 2、end 是 3(正在处理第 2 个,共 3 个),done 里是已经执行的 pick F1、pick F2,git-rebase-todo 里只剩 pick F3。git status 显示 interactive rebase in progress; onto … 和 Last commands done (2 commands done)。解决冲突后 git rebase --continue 输出 Rebasing (3/3) 和 Successfully rebased and updated refs/heads/feature.,.git/rebase-merge 目录随之删除。", t=tl(S(3)), mark=lidx(S(3), 'head-name', 'msgnum', 'end       3', 'pick <sha> # F3', 'Last commands done'), done=lidx(S(3), 'CONFLICT (add/add)', 'done:', 'Successfully rebased', '完成后 .git/rebase-merge'), kv=KV([['rebase-merge/', '一次 rebase 的全部状态'], ['todo / done', '还剩什么 / 已经做了什么'], ['onto / orig-head', '新基础 / 旧末端'], ['完成', '目录被删除']], ['rebase-merge/'])),
    step("上游已经有的补丁会被丢弃:main 用 cherry-pick -x 拿走了 feature 上的 F2,git rebase main 输出 warning: skipped previously applied commit <sha> 和 hint: use --reapply-cherry-picks to include skipped commits,只重放 F1,结果 main..feature 里只剩 F1。判断依据是 patch-id(补丁内容的指纹);git cherry -v main feature 也只把 F1 标成 + (还没在上游),F2 因为上游有等价补丁而不出现。", t=tl(S(4)), mark=lidx(S(4), 'skipped previously applied commit', 'reapply-cherry-picks', '+ <sha40> F1'), done=lidx(S(4), 'Successfully rebased', '  F1'), kv=KV([['重复的补丁', 'rebase 自动跳过'], ['依据', 'patch-id'], ['保留它们', '--reapply-cherry-picks']], ['patch-id'])),
    step("feature 已经包含 main 的全部提交时(main 没有新提交),git rebase main 输出 Current branch feature is up to date.,什么都不用重放,也不会改写任何提交。", t=tl(S(5)), mark=lidx(S(5), 'up to date'), done=lidx(S(5), 'git rebase main'), kv=KV([['无事可做', 'up to date'], ['没有改写', '没有新 hash']], ['无事可做'])),
]
A = mkarti('l45', 45, 'Git,rebase,range-diff,patch-id,真实验证,动画演示',
    '拆开 git rebase:feature 上的 3 个提交变成 3 个新提交(parent 链和 tree 都变,作者保留、提交者变成执行者);旧提交靠 ORIG_HEAD 和 reflog 保留,git range-diff 把新旧一一配对;冲突停下时 .git/rebase-merge 记录 head-name、onto、orig-head、todo/done 与进度;上游已有的等价补丁(patch-id 相同)自动跳过;无事可做时 up to date。',
    'rebase 把提交“搬”到新的基础上,原来的提交去哪了?中途停下来时 git 把进度记在哪里?为什么有些提交会被悄悄跳过?这篇用一个小例子把 rebase 拆开,逐项对账。',
    [('3 → 3', 'rebase 之后 3 个提交都有了新的 hash(parent 变了),旧的 3 个仍可通过 ORIG_HEAD 和 reflog 找到'), ('range-diff', '把新旧两组提交一一配对,= 表示改动相同、只是基础变了'), ('patch-id', 'rebase 靠它识别上游已经有的等价补丁并跳过')],
    [('重放', '<p>rebase 做的事:找出 <code>upstream..分支</code> 的提交列表,把每个提交的改动在新基础上重新应用(本质上是一次次 cherry-pick),分支指针最后移到新的末端。新提交的作者不变,提交者与时间是现在的,parent 链和 tree 都不同,所以 hash 全部是新的。</p>'),
     ('旧提交', '<p>旧提交不会立刻消失:<code>ORIG_HEAD</code> 指向旧的末端,reflog 里有 <code>rebase (start)</code>、每个 <code>rebase (pick)</code> 和 <code>rebase (finish)</code>。没有分支包含它们,所以只能通过这些间接引用找到;<code>git range-diff</code> 能把新旧提交一一对应起来。</p>'),
     ('状态目录', '<p>rebase 中途停下时,<code>.git/rebase-merge/</code> 记着:正在改写的分支(<code>head-name</code>)、新基础(<code>onto</code>)、旧末端(<code>orig-head</code>)、进度(<code>msgnum</code>、<code>end</code>)、已完成的 <code>done</code> 与待办的 <code>git-rebase-todo</code>。<code>--continue</code> 或 <code>--abort</code> 之后目录被删除。</p>'),
     ('跳过重复', '<p>如果上游已经有等价的补丁(patch-id 相同),rebase 会跳过那个提交并警告;<code>--reapply-cherry-picks</code> 可以保留它。</p>'),
     ('无事可做', '<p>当前分支已经包含 upstream 的全部提交时,rebase 直接报告 up to date,不改写任何提交。</p>')],
    steps,
    [ENV_I_GIT + '。提交时间固定,Bob 的 rebase 时间也固定,所以 hash 可复现;range-diff 一节显示的是实验中的 hash',
     '没有验证:rebase --interactive 的 todo 命令(见下一篇);--rebase-merges、--onto 的用法(--onto 在 merge-base 一篇出现过);rebase 对合并提交的处理;autosquash、autostash;rebase.backend 的 apply 与 merge 两种实现(本机默认 merge);空提交的处理'],
    'rebase 的实现')
